import { PrismaClient, Score, MainDimension, SubDimension, Aspect, SubCategory, Prisma } from '@prisma/client';
import { hierarchyService } from './hierarchy-service';

const prisma = new PrismaClient();

export interface MarketData {
  rsi?: number;
  macd?: number;
  macdSignal?: number;
  bollingerUpper?: number;
  bollingerMiddle?: number;
  bollingerLower?: number;
  price?: number;
  volume?: number;
  [key: string]: unknown;
}

export interface ScoreCalculationInput {
  symbolId: string;
  marketData: MarketData; // داده‌های بازار
  calculationDate: Date;
  validFrom: Date;
  validTo?: Date;
}

export interface DimensionScoreResult {
  dimensionId: string;
  dimensionCode: string;
  dimensionName: string;
  level: 'main' | 'sub' | 'aspect' | 'category';
  value: number;
  normalizedValue: number;
  weight: number;
  confidence: number;
  factors: Array<{
    name: string;
    value: number;
    weight: number;
    description?: string;
  }>;
}

export interface ScoreMetadata {
  confidence?: number;
  factors?: string[];
}

export interface SymbolScoreSummary {
  symbolId: string;
  symbolCode: string;
  symbolName: string;
  totalScore: number;
  weightedScore: number;
  rank?: number;
  dimensions: DimensionScoreResult[];
  calculationDate: Date;
  validFrom: Date;
  validTo?: Date;
}

export interface ScoringAlgorithm {
  name: string;
  description: string;
  calculate: (input: ScoreCalculationInput) => Promise<DimensionScoreResult[]>;
}

/**
 * سرویس سیستم امتیازدهی 6D
 * مسئولیت: محاسبه، ذخیره و مدیریت امتیازهای 6 بعدی برای نمادها
 */
export class ScoringService {
  private algorithms: Map<string, ScoringAlgorithm> = new Map();

  constructor() {
    this.registerDefaultAlgorithms();
  }

  /**
   * ثبت الگوریتم‌های پیش‌فرض
   */
  private registerDefaultAlgorithms() {
    // الگوریتم تحلیل تکنیکال
    this.algorithms.set('technical-analysis', {
      name: 'تحلیل تکنیکال',
      description: 'محاسبه امتیاز بر اساس اندیکاتورهای تکنیکال',
      calculate: async (input: ScoreCalculationInput) => {
        const marketData = input.marketData;
        const results: DimensionScoreResult[] = [];

        // محاسبه RSI Score (TA-01)
        const rsiScore = this.calculateRSIScore(marketData.rsi);
        results.push({
          dimensionId: '', // بعداً پر می‌شود
          dimensionCode: 'TA-01',
          dimensionName: 'شاخص قدرت نسبی (RSI)',
          level: 'category',
          value: rsiScore.value,
          normalizedValue: rsiScore.normalized,
          weight: 0.15,
          confidence: 0.85,
          factors: [
            { name: 'RSI Value', value: marketData.rsi || 50, weight: 1.0, description: 'مقدار RSI فعلی' },
            { name: 'Oversold', value: marketData.rsi < 30 ? 1 : 0, weight: 0.3, description: 'وضعیت اشباع فروش' },
            { name: 'Overbought', value: marketData.rsi > 70 ? 1 : 0, weight: 0.3, description: 'وضعیت اشباع خرید' }
          ]
        });

        // محاسبه MACD Score (TA-02)
        const macdScore = this.calculateMACDScore(marketData.macd, marketData.macdSignal);
        results.push({
          dimensionId: '',
          dimensionCode: 'TA-02',
          dimensionName: 'میانگین متحرک همگرایی-واگرایی (MACD)',
          level: 'category',
          value: macdScore.value,
          normalizedValue: macdScore.normalized,
          weight: 0.15,
          confidence: 0.80,
          factors: [
            { name: 'MACD Line', value: marketData.macd || 0, weight: 0.6, description: 'خط MACD' },
            { name: 'Signal Line', value: marketData.macdSignal || 0, weight: 0.4, description: 'خط سیگنال' },
            { name: 'Crossover', value: this.detectMACDCrossover(marketData.macd, marketData.macdSignal), weight: 0.5, description: 'شناسایی تقاطع' }
          ]
        });

        // محاسبه Bollinger Bands Score (TA-03)
        const bbScore = this.calculateBollingerScore(marketData.bollingerWidth, marketData.price);
        results.push({
          dimensionId: '',
          dimensionCode: 'TA-03',
          dimensionName: 'باندهای بولینگر',
          level: 'category',
          value: bbScore.value,
          normalizedValue: bbScore.normalized,
          weight: 0.12,
          confidence: 0.75,
          factors: [
            { name: 'Band Width', value: marketData.bollingerWidth || 10, weight: 0.7, description: 'عرض باندها' },
            { name: 'Price Position', value: this.calculatePricePositionInBB(marketData.price), weight: 0.3, description: 'موقعیت قیمت در باند' }
          ]
        });

        return results;
      }
    });

    // الگوریتم تحلیل بنیادی
    this.algorithms.set('fundamental-analysis', {
      name: 'تحلیل بنیادی',
      description: 'محاسبه امتیاز بر اساس شاخص‌های بنیادی',
      calculate: async (input: ScoreCalculationInput) => {
        const marketData = input.marketData;
        const results: DimensionScoreResult[] = [];

        // محاسبه P/E Score (FA-01)
        const peScore = this.calculatePEScore(marketData.pe);
        results.push({
          dimensionId: '',
          dimensionCode: 'FA-01',
          dimensionName: 'نسبت قیمت به درآمد (P/E)',
          level: 'category',
          value: peScore.value,
          normalizedValue: peScore.normalized,
          weight: 0.20,
          confidence: 0.90,
          factors: [
            { name: 'P/E Ratio', value: marketData.pe || 15, weight: 1.0, description: 'نسبت P/E فعلی' },
            { name: 'Industry Avg', value: 18, weight: 0.3, description: 'میانگین صنعت' },
            { name: 'Historical Avg', value: 16, weight: 0.2, description: 'میانگین تاریخی' }
          ]
        });

        // محاسبه ROE Score (FA-06)
        const roeScore = this.calculateROEScore(marketData.roe);
        results.push({
          dimensionId: '',
          dimensionCode: 'FA-06',
          dimensionName: 'بازده حقوق صاحبان سهام (ROE)',
          level: 'category',
          value: roeScore.value,
          normalizedValue: roeScore.normalized,
          weight: 0.18,
          confidence: 0.85,
          factors: [
            { name: 'ROE %', value: marketData.roe || 15, weight: 1.0, description: 'درصد ROE' },
            { name: 'Trend', value: this.assumePositiveTrend(), weight: 0.4, description: 'روند تغییرات' }
          ]
        });

        // محاسبه Debt-to-Equity Score (FA-11)
        const deScore = this.calculateDebtEquityScore(marketData.debtToEquity);
        results.push({
          dimensionId: '',
          dimensionCode: 'FA-11',
          dimensionName: 'نسبت بدهی به حقوق صاحبان سهام',
          level: 'category',
          value: deScore.value,
          normalizedValue: deScore.normalized,
          weight: 0.15,
          confidence: 0.80,
          factors: [
            { name: 'D/E Ratio', value: marketData.debtToEquity || 0.5, weight: 1.0, description: 'نسبت D/E' },
            { name: 'Risk Level', value: this.calculateRiskLevel(marketData.debtToEquity), weight: 0.5, description: 'سطح ریسک' }
          ]
        });

        return results;
      }
    });
  }

  /**
   * محاسبه امتیاز کامل برای یک نماد
   */
  async calculateScores(input: ScoreCalculationInput): Promise<SymbolScoreSummary> {
    try {
      // دریافت اطلاعات نماد
      const symbol = await prisma.symbol.findUnique({
        where: { id: input.symbolId },
        select: { id: true, symbol: true, name: true }
      });

      if (!symbol) {
        throw new Error('نماد مورد نظر یافت نشد');
      }

      // اجرای تمام الگوریتم‌ها
      const allResults: DimensionScoreResult[] = [];
      
      for (const [algorithmId, algorithm] of this.algorithms.entries()) {
        try {
          const results = await algorithm.calculate(input);
          allResults.push(...results);
        } catch (error) {
          console.error(`خطا در اجرای الگوریتم ${algorithmId}:`, error);
        }
      }

      // تطبیق نتایج با ساختار سلسله‌مراتبی
      const hierarchy = await hierarchyService.getFullHierarchy();
      const dimensionResults: DimensionScoreResult[] = [];

      // تطبیق هر نتیجه با گره مناسب در سلسله‌مراتب
      for (const result of allResults) {
        // یافتن گره متناظر بر اساس کد
        let matchedNode: MainDimension | SubDimension | Aspect | SubCategory | null = null;
        
        for (const mainDim of hierarchy.mainDimensions) {
          if (mainDim.code === result.dimensionCode) {
            matchedNode = mainDim;
            result.dimensionId = mainDim.id;
            result.dimensionName = mainDim.name;
            result.level = 'main';
            break;
          }
          
          for (const subDim of mainDim.subDimensions) {
            if (subDim.code === result.dimensionCode) {
              matchedNode = subDim;
              result.dimensionId = subDim.id;
              result.dimensionName = subDim.name;
              result.level = 'sub';
              break;
            }
            
            for (const aspect of subDim.aspects) {
              if (aspect.code === result.dimensionCode) {
                matchedNode = aspect;
                result.dimensionId = aspect.id;
                result.dimensionName = aspect.name;
                result.level = 'aspect';
                break;
              }
              
              for (const category of aspect.subCategories) {
                if (category.code === result.dimensionCode) {
                  matchedNode = category;
                  result.dimensionId = category.id;
                  result.dimensionName = category.name;
                  result.level = 'category';
                  break;
                }
              }
            }
          }
        }

        if (matchedNode) {
          dimensionResults.push(result);
        }
      }

      // محاسبه امتیاز کل
      const totalScore = this.calculateTotalScore(dimensionResults);
      const weightedScore = this.calculateWeightedScore(dimensionResults);

      // ذخیره امتیازها در دیتابیس
      await this.saveScores(
        input.symbolId,
        dimensionResults,
        input.calculationDate,
        input.validFrom,
        input.validTo
      );

      return {
        symbolId: symbol.id,
        symbolCode: symbol.symbol,
        symbolName: symbol.name,
        totalScore,
        weightedScore,
        dimensions: dimensionResults,
        calculationDate: input.calculationDate,
        validFrom: input.validFrom,
        validTo: input.validTo
      };
    } catch (error) {
      console.error('خطا در محاسبه امتیازها:', error);
      throw new Error('خطا در محاسبه امتیازها');
    }
  }

  /**
   * دریافت امتیازهای یک نماد
   */
  async getSymbolScores(symbolId: string, options?: {
    includeDimensions?: boolean;
    includeHistory?: boolean;
    limit?: number;
  }): Promise<{
    currentScores: Score[];
    dimensionScores?: DimensionScoreResult[];
    history?: Score[];
  }> {
    try {
      const currentScores = await prisma.score.findMany({
        where: {
          symbolId,
          validTo: { gte: new Date() }
        },
        orderBy: { calculationDate: 'desc' },
        take: options?.limit || 100
      });

      const result: {
        currentScores: Score[];
        dimensionScores?: DimensionScoreResult[];
        history?: Score[];
      } = { currentScores };

      if (options?.includeDimensions) {
        // گروه‌بندی امتیازها بر اساس ابعاد
        const dimensionScores = await this.groupScoresByDimension(currentScores);
        result.dimensionScores = dimensionScores;
      }

      if (options?.includeHistory) {
        const history = await prisma.score.findMany({
          where: { symbolId },
          orderBy: { calculationDate: 'desc' },
          take: 50
        });
        result.history = history;
      }

      return result;
    } catch (error) {
      console.error('خطا در دریافت امتیازهای نماد:', error);
      throw new Error('خطا در دریافت امتیازهای نماد');
    }
  }

  /**
   * دریافت رتبه‌بندی نمادها
   */
  async getSymbolRankings(options?: {
    dimensionId?: string;
    limit?: number;
    offset?: number;
    minScore?: number;
    maxScore?: number;
  }): Promise<Array<{
    symbolId: string;
    symbolCode: string;
    symbolName: string;
    score: number;
    weightedScore: number;
    rank: number;
    calculationDate: Date;
  }>> {
    try {
      // دریافت آخرین امتیازهای هر نماد
      const latestScores = await prisma.$queryRaw`
        WITH LatestScores AS (
          SELECT 
            s.symbolId,
            s.value,
            s.normalizedValue,
            s.weight,
            s.calculationDate,
            sym.symbol as symbolCode,
            sym.name as symbolName,
            ROW_NUMBER() OVER (PARTITION BY s.symbolId ORDER BY s.calculationDate DESC) as rn
          FROM Score s
          JOIN Symbol sym ON s.symbolId = sym.id
          WHERE s.validTo >= CURRENT_TIMESTAMP
          ${options?.dimensionId ? Prisma.sql`AND s.mainDimensionId = ${options.dimensionId}` : Prisma.sql``}
          ${options?.minScore ? Prisma.sql`AND s.value >= ${options.minScore}` : Prisma.sql``}
          ${options?.maxScore ? Prisma.sql`AND s.value <= ${options.maxScore}` : Prisma.sql``}
        )
        SELECT 
          symbolId,
          symbolCode,
          symbolName,
          value as score,
          normalizedValue as weightedScore,
          calculationDate
        FROM LatestScores
        WHERE rn = 1
        ORDER BY normalizedValue DESC
        LIMIT ${options?.limit || 50}
        OFFSET ${options?.offset || 0}
      `;

      // اضافه کردن رتبه
      const rankings = latestScores.map((item, index) => ({
        ...item,
        rank: index + 1
      }));

      return rankings;
    } catch (error) {
      console.error('خطا در دریافت رتبه‌بندی نمادها:', error);
      throw new Error('خطا در دریافت رتبه‌بندی نمادها');
    }
  }

  /**
   * به‌روزرسانی وزن‌های امتیازدهی
   */
  async updateScoreWeights(updates: Array<{
    scoreId: string;
    newWeight: number;
  }>): Promise<void> {
    try {
      await prisma.$transaction(async (tx) => {
        for (const update of updates) {
          await tx.score.update({
            where: { id: update.scoreId },
            data: { weight: update.newWeight }
          });
        }
      });
    } catch (error) {
      console.error('خطا در به‌روزرسانی وزن‌ها:', error);
      throw new Error('خطا در به‌روزرسانی وزن‌ها');
    }
  }

  /**
   * ثبت الگوریتم جدید
   */
  registerAlgorithm(id: string, algorithm: ScoringAlgorithm): void {
    this.algorithms.set(id, algorithm);
  }

  /**
   * دریافت لیست الگوریتم‌های موجود
   */
  getAvailableAlgorithms(): Array<{
    id: string;
    name: string;
    description: string;
  }> {
    return Array.from(this.algorithms.entries()).map(([id, algorithm]) => ({
      id,
      name: algorithm.name,
      description: algorithm.description
    }));
  }

  // ============================================================================
  // متدهای کمکی محاسباتی
  // ============================================================================

  private calculateRSIScore(rsi: number): { value: number; normalized: number } {
    // RSI بین 0-100 است، امتیاز بهینه بین 30-70
    const normalized = Math.max(0, Math.min(100, rsi));
    let score = 50; // امتیاز پایه
    
    if (normalized >= 30 && normalized <= 70) {
      // منطقه بهینه
      score = 70 + (40 - Math.abs(50 - normalized)) * 0.75;
    } else if (normalized < 30) {
      // اشباع فروش
      score = 30 + normalized;
    } else {
      // اشباع خرید
      score = 100 - (normalized - 70);
    }
    
    return {
      value: score,
      normalized: score / 100
    };
  }

  private calculateMACDScore(macd: number, signal: number): { value: number; normalized: number } {
    // تفاوت بین MACD و Signal Line
    const diff = (macd || 0) - (signal || 0);
    let score = 50;
    
    if (diff > 0) {
      // روند صعودی
      score = 60 + Math.min(40, diff * 10);
    } else {
      // روند نزولی
      score = 40 - Math.min(40, Math.abs(diff) * 10);
    }
    
    return {
      value: score,
      normalized: score / 100
    };
  }

  private calculateBollingerScore(width: number): { value: number; normalized: number } {
    // عرض باند نشان‌دهنده نوسان است
    const normalizedWidth = Math.min(30, width || 10);
    let score = 50;
    
    if (normalizedWidth < 15) {
      // نوسان کم - بازار آرام
      score = 60 + (15 - normalizedWidth) * 2;
    } else if (normalizedWidth > 25) {
      // نوسان زیاد - بازار پرنوسان
      score = 40 - (normalizedWidth - 25);
    }
    
    return {
      value: score,
      normalized: score / 100
    };
  }

  private calculatePEScore(pe: number): { value: number; normalized: number } {
    // P/E بهینه بین 10-20
    const normalizedPE = pe || 15;
    let score = 50;
    
    if (normalizedPE >= 10 && normalizedPE <= 20) {
      // منطقه بهینه
      score = 80 - Math.abs(15 - normalizedPE) * 3;
    } else if (normalizedPE < 10) {
      // ارزنده
      score = 90 - (10 - normalizedPE) * 2;
    } else {
      // گران
      score = 60 - (normalizedPE - 20);
    }
    
    return {
      value: Math.max(0, Math.min(100, score)),
      normalized: Math.max(0, Math.min(1, score / 100))
    };
  }

  private calculateROEScore(roe: number): { value: number; normalized: number } {
    // ROE بهینه بالای 15%
    const normalizedROE = roe || 15;
    let score = 50;
    
    if (normalizedROE >= 15) {
      score = 70 + Math.min(30, (normalizedROE - 15) * 2);
    } else {
      score = 30 + normalizedROE * 2;
    }
    
    return {
      value: Math.max(0, Math.min(100, score)),
      normalized: Math.max(0, Math.min(1, score / 100))
    };
  }

  private calculateDebtEquityScore(deRatio: number): { value: number; normalized: number } {
    // نسبت D/E بهینه زیر 1
    const normalizedDE = deRatio || 0.5;
    let score = 50;
    
    if (normalizedDE <= 1) {
      // وضعیت خوب
      score = 80 - normalizedDE * 30;
    } else {
      // بدهی بالا
      score = 50 - (normalizedDE - 1) * 20;
    }
    
    return {
      value: Math.max(0, Math.min(100, score)),
      normalized: Math.max(0, Math.min(1, score / 100))
    };
  }

  private detectMACDCrossover(macd: number, signal: number): number {
    if (!macd || !signal) return 0;
    return macd > signal ? 1 : -1;
  }

  private calculatePricePositionInBB(): number {
    // شبیه‌سازی موقعیت قیمت در باندهای بولینگر
    return 0.5;
  }

  private assumePositiveTrend(): number {
    // شبیه‌سازی روند مثبت
    return 0.7;
  }

  private calculateRiskLevel(deRatio: number): number {
    // محاسبه سطح ریسک بر اساس نسبت D/E
    if (!deRatio) return 0.3;
    return Math.min(1, deRatio / 2);
  }

  private calculateTotalScore(dimensionResults: DimensionScoreResult[]): number {
    if (dimensionResults.length === 0) return 0;
    
    const sum = dimensionResults.reduce((total, result) => total + result.value, 0);
    return sum / dimensionResults.length;
  }

  private calculateWeightedScore(dimensionResults: DimensionScoreResult[]): number {
    if (dimensionResults.length === 0) return 0;
    
    const weightedSum = dimensionResults.reduce((total, result) => 
      total + (result.value * result.weight), 0);
    const totalWeight = dimensionResults.reduce((total, result) => total + result.weight, 0);
    
    return totalWeight > 0 ? weightedSum / totalWeight : 0;
  }

  private async saveScores(
    symbolId: string,
    dimensionResults: DimensionScoreResult[],
    calculationDate: Date,
    validFrom: Date,
    validTo?: Date
  ): Promise<void> {
    try {
      await prisma.$transaction(async (tx) => {
        for (const result of dimensionResults) {
          await tx.score.create({
            data: {
              value: result.value,
              normalizedValue: result.normalizedValue,
              weight: result.weight,
              mainDimensionId: result.level === 'main' ? result.dimensionId : undefined,
              subDimensionId: result.level === 'sub' ? result.dimensionId : undefined,
              aspectId: result.level === 'aspect' ? result.dimensionId : undefined,
              subCategoryId: result.level === 'category' ? result.dimensionId : undefined,
              symbolId,
              calculationDate,
              validFrom,
              validTo,
              metadata: {
                confidence: result.confidence,
                factors: result.factors,
                calculationDate: calculationDate.toISOString()
              }
            }
          });
        }
      });
    } catch (error) {
      console.error('خطا در ذخیره امتیازها:', error);
      throw error;
    }
  }

  private async groupScoresByDimension(scores: Score[]): Promise<DimensionScoreResult[]> {
    // گروه‌بندی امتیازها بر اساس ابعاد
    const dimensionMap = new Map<string, DimensionScoreResult>();
    
    for (const score of scores) {
      const dimensionId = score.mainDimensionId || score.subDimensionId || score.aspectId || score.subCategoryId;
      
      if (!dimensionId) continue;
      
      const key = dimensionId;
      
      if (!dimensionMap.has(key)) {
        // دریافت اطلاعات بعد
        let dimensionInfo: MainDimension | SubDimension | Aspect | SubCategory | null = null;
        
        if (score.mainDimensionId) {
          dimensionInfo = await prisma.mainDimension.findUnique({
            where: { id: score.mainDimensionId }
          });
        } else if (score.subDimensionId) {
          dimensionInfo = await prisma.subDimension.findUnique({
            where: { id: score.subDimensionId }
          });
        } else if (score.aspectId) {
          dimensionInfo = await prisma.aspect.findUnique({
            where: { id: score.aspectId }
          });
        } else if (score.subCategoryId) {
          dimensionInfo = await prisma.subCategory.findUnique({
            where: { id: score.subCategoryId }
          });
        }
        
        dimensionMap.set(key, {
          dimensionId,
          dimensionCode: dimensionInfo?.code || 'UNKNOWN',
          dimensionName: dimensionInfo?.name || 'نامشخص',
          level: score.mainDimensionId ? 'main' : 
                 score.subDimensionId ? 'sub' : 
                 score.aspectId ? 'aspect' : 'category',
          value: score.value,
          normalizedValue: score.normalizedValue,
          weight: score.weight,
          confidence: (score.metadata as ScoreMetadata)?.confidence || 0.5,
          factors: (score.metadata as ScoreMetadata)?.factors || []
        });
      }
    }
    
    return Array.from(dimensionMap.values());
  }
}

// ایجاد نمونه singleton از سرویس
export const scoringService = new ScoringService();