import { PrismaClient } from '@prisma/client';
import { 
  MainDimension, 
  SubDimension, 
  Aspect, 
  SubCategory 
} from '@prisma/client';

const prisma = new PrismaClient();

export interface HierarchyNode {
  id: string;
  code: string;
  name: string;
  description?: string;
  weight: number;
  order: number;
  level: 'main' | 'sub' | 'aspect' | 'category';
  children?: HierarchyNode[];
}

export interface FullHierarchy {
  mainDimensions: Array<{
    id: string;
    code: string;
    name: string;
    description?: string;
    weight: number;
    order: number;
    subDimensions: Array<{
      id: string;
      code: string;
      name: string;
      description?: string;
      weight: number;
      order: number;
      aspects: Array<{
        id: string;
        code: string;
        name: string;
        description?: string;
        weight: number;
        order: number;
        subCategories: Array<{
          id: string;
          code: string;
          name: string;
          description?: string;
          weight: number;
          order: number;
        }>;
      }>;
    }>;
  }>;
}

/**
 * سرویس مدیریت سلسله‌مراتب 6D
 * مسئولیت: مدیریت کامل ساختار سلسله‌مراتبی 6 بعدی
 */
export class HierarchyService {
  
  /**
   * دریافت کامل ساختار سلسله‌مراتبی
   */
  async getFullHierarchy(): Promise<FullHierarchy> {
    try {
      const mainDimensions = await prisma.mainDimension.findMany({
        include: {
          subDimensions: {
            include: {
              aspects: {
                include: {
                  subCategories: {
                    orderBy: { order: 'asc' }
                  }
                },
                orderBy: { order: 'asc' }
              }
            },
            orderBy: { order: 'asc' }
          }
        },
        orderBy: { order: 'asc' }
      });

      return {
        mainDimensions: mainDimensions.map(md => ({
          id: md.id,
          code: md.code,
          name: md.name,
          description: md.description || undefined,
          weight: md.weight,
          order: md.order,
          subDimensions: md.subDimensions.map(sd => ({
            id: sd.id,
            code: sd.code,
            name: sd.name,
            description: sd.description || undefined,
            weight: sd.weight,
            order: sd.order,
            aspects: sd.aspects.map(as => ({
              id: as.id,
              code: as.code,
              name: as.name,
              description: as.description || undefined,
              weight: as.weight,
              order: as.order,
              subCategories: as.subCategories.map(sc => ({
                id: sc.id,
                code: sc.code,
                name: sc.name,
                description: sc.description || undefined,
                weight: sc.weight,
                order: sc.order
              }))
            }))
          }))
        }))
      };
    } catch (error) {
      console.error('خطا در دریافت ساختار سلسله‌مراتبی:', error);
      throw new Error('خطا در دریافت ساختار سلسله‌مراتبی');
    }
  }

  /**
   * دریافت ساختار درختی برای نمایش
   */
  async getHierarchyTree(): Promise<HierarchyNode[]> {
    try {
      const mainDimensions = await prisma.mainDimension.findMany({
        include: {
          subDimensions: {
            include: {
              aspects: {
                include: {
                  subCategories: true
                }
              }
            }
          }
        },
        orderBy: { order: 'asc' }
      });

      return mainDimensions.map(md => this.mapToHierarchyNode(md));
    } catch (error) {
      console.error('خطا در دریافت درخت سلسله‌مراتبی:', error);
      throw new Error('خطا در دریافت درخت سلسله‌مراتبی');
    }
  }

  /**
   * ایجاد بعد اصلی جدید
   */
  async createMainDimension(data: {
    code: string;
    name: string;
    description?: string;
    weight?: number;
    order: number;
  }): Promise<MainDimension> {
    try {
      // بررسی تکراری نبودن کد
      const existing = await prisma.mainDimension.findUnique({
        where: { code: data.code }
      });

      if (existing) {
        throw new Error(`کد ${data.code} قبلاً استفاده شده است`);
      }

      // بررسی تکراری نبودن ترتیب
      const existingOrder = await prisma.mainDimension.findUnique({
        where: { order: data.order }
      });

      if (existingOrder) {
        throw new Error(`ترتیب ${data.order} قبلاً استفاده شده است`);
      }

      return await prisma.mainDimension.create({
        data: {
          code: data.code,
          name: data.name,
          description: data.description,
          weight: data.weight || 1.0,
          order: data.order
        }
      });
    } catch (error) {
      console.error('خطا در ایجاد بعد اصلی:', error);
      throw error;
    }
  }

  /**
   * ایجاد زیربعد جدید
   */
  async createSubDimension(data: {
    code: string;
    name: string;
    description?: string;
    weight?: number;
    order: number;
    mainDimensionId: string;
  }): Promise<SubDimension> {
    try {
      // بررسی وجود بعد اصلی
      const mainDim = await prisma.mainDimension.findUnique({
        where: { id: data.mainDimensionId }
      });

      if (!mainDim) {
        throw new Error('بعد اصلی مورد نظر یافت نشد');
      }

      // بررسی تکراری نبودن کد در این بعد اصلی
      const existingCode = await prisma.subDimension.findFirst({
        where: {
          code: data.code,
          mainDimensionId: data.mainDimensionId
        }
      });

      if (existingCode) {
        throw new Error(`کد ${data.code} قبلاً در این بعد اصلی استفاده شده است`);
      }

      // بررسی تکراری نبودن ترتیب در این بعد اصلی
      const existingOrder = await prisma.subDimension.findFirst({
        where: {
          order: data.order,
          mainDimensionId: data.mainDimensionId
        }
      });

      if (existingOrder) {
        throw new Error(`ترتیب ${data.order} قبلاً در این بعد اصلی استفاده شده است`);
      }

      return await prisma.subDimension.create({
        data: {
          code: data.code,
          name: data.name,
          description: data.description,
          weight: data.weight || 1.0,
          order: data.order,
          mainDimensionId: data.mainDimensionId
        }
      });
    } catch (error) {
      console.error('خطا در ایجاد زیربعد:', error);
      throw error;
    }
  }

  /**
   * به‌روزرسانی وزن یک گره در سلسله‌مراتب
   */
  async updateNodeWeight(nodeId: string, level: HierarchyNode['level'], newWeight: number): Promise<void> {
    try {
      if (newWeight < 0 || newWeight > 10) {
        throw new Error('وزن باید بین 0 تا 10 باشد');
      }

      switch (level) {
        case 'main':
          await prisma.mainDimension.update({
            where: { id: nodeId },
            data: { weight: newWeight }
          });
          break;
        case 'sub':
          await prisma.subDimension.update({
            where: { id: nodeId },
            data: { weight: newWeight }
          });
          break;
        case 'aspect':
          await prisma.aspect.update({
            where: { id: nodeId },
            data: { weight: newWeight }
          });
          break;
        case 'category':
          await prisma.subCategory.update({
            where: { id: nodeId },
            data: { weight: newWeight }
          });
          break;
        default:
          throw new Error('سطح گره نامعتبر است');
      }
    } catch (error) {
      console.error('خطا در به‌روزرسانی وزن:', error);
      throw error;
    }
  }

  /**
   * حذف یک گره از سلسله‌مراتب
   */
  async deleteNode(nodeId: string, level: HierarchyNode['level']): Promise<void> {
    try {
      switch (level) {
        case 'main': {
          // بررسی وجود زیربعد‌ها قبل از حذف
          const subDims = await prisma.subDimension.count({
            where: { mainDimensionId: nodeId }
          });
          
          if (subDims > 0) {
            throw new Error('امکان حذف بعد اصلی با زیربعد‌های موجود وجود ندارد');
          }
          
          await prisma.mainDimension.delete({
            where: { id: nodeId }
          });
          break;
        }
        case 'sub': {
          // بررسی وجود جنبه‌ها قبل از حذف
          const aspects = await prisma.aspect.count({
            where: { subDimensionId: nodeId }
          });
          
          if (aspects > 0) {
            throw new Error('امکان حذف زیربعد با جنبه‌های موجود وجود ندارد');
          }
          
          await prisma.subDimension.delete({
            where: { id: nodeId }
          });
          break;
        }
        case 'aspect': {
          // بررسی وجود زیرمجموعه‌ها قبل از حذف
          const categories = await prisma.subCategory.count({
            where: { aspectId: nodeId }
          });
          
          if (categories > 0) {
            throw new Error('امکان حذف جنبه با زیرمجموعه‌های موجود وجود ندارد');
          }
          
          await prisma.aspect.delete({
            where: { id: nodeId }
          });
          break;
        }
        case 'category':
          await prisma.subCategory.delete({
            where: { id: nodeId }
          });
          break;
        default:
          throw new Error('سطح گره نامعتبر است');
      }
    } catch (error) {
      console.error('خطا در حذف گره:', error);
      throw error;
    }
  }

  /**
   * جستجوی گره‌ها بر اساس نام یا کد
   */
  async searchNodes(query: string): Promise<HierarchyNode[]> {
    try {
      // جستجو در تمام سطوح
      const [mainDims, subDims, aspects, categories] = await Promise.all([
        prisma.mainDimension.findMany({
          where: {
            OR: [
              { name: { contains: query } },
              { code: { contains: query } }
            ]
          }
        }),
        prisma.subDimension.findMany({
          where: {
            OR: [
              { name: { contains: query } },
              { code: { contains: query } }
            ]
          }
        }),
        prisma.aspect.findMany({
          where: {
            OR: [
              { name: { contains: query } },
              { code: { contains: query } }
            ]
          }
        }),
        prisma.subCategory.findMany({
          where: {
            OR: [
              { name: { contains: query } },
              { code: { contains: query } }
            ]
          }
        })
      ]);

      const nodes: HierarchyNode[] = [
        ...mainDims.map(md => ({
          id: md.id,
          code: md.code,
          name: md.name,
          description: md.description || undefined,
          weight: md.weight,
          order: md.order,
          level: 'main' as const
        })),
        ...subDims.map(sd => ({
          id: sd.id,
          code: sd.code,
          name: sd.name,
          description: sd.description || undefined,
          weight: sd.weight,
          order: sd.order,
          level: 'sub' as const
        })),
        ...aspects.map(as => ({
          id: as.id,
          code: as.code,
          name: as.name,
          description: as.description || undefined,
          weight: as.weight,
          order: as.order,
          level: 'aspect' as const
        })),
        ...categories.map(sc => ({
          id: sc.id,
          code: sc.code,
          name: sc.name,
          description: sc.description || undefined,
          weight: sc.weight,
          order: sc.order,
          level: 'category' as const
        }))
      ];

      return nodes;
    } catch (error) {
      console.error('خطا در جستجوی گره‌ها:', error);
      throw new Error('خطا در جستجوی گره‌ها');
    }
  }

  /**
   * بررسی صحت ساختار سلسله‌مراتبی
   */
  async validateHierarchy(): Promise<{
    isValid: boolean;
    issues: Array<{
      level: HierarchyNode['level'];
      nodeId: string;
      nodeName: string;
      issue: string;
    }>;
  }> {
    try {
      const issues: Array<{
        level: HierarchyNode['level'];
        nodeId: string;
        nodeName: string;
        issue: string;
      }> = [];

      // بررسی بعدهای اصلی
      const mainDims = await prisma.mainDimension.findMany({
        orderBy: { order: 'asc' }
      });

      // بررسی ترتیب تکراری
      const orderSet = new Set<number>();
      mainDims.forEach(md => {
        if (orderSet.has(md.order)) {
          issues.push({
            level: 'main',
            nodeId: md.id,
            nodeName: md.name,
            issue: `ترتیب تکراری: ${md.order}`
          });
        }
        orderSet.add(md.order);
      });

      // بررسی وزن‌های معتبر
      mainDims.forEach(md => {
        if (md.weight < 0 || md.weight > 10) {
          issues.push({
            level: 'main',
            nodeId: md.id,
            nodeName: md.name,
            issue: `وزن نامعتبر: ${md.weight} (باید بین 0 تا 10 باشد)`
          });
        }
      });

      return {
        isValid: issues.length === 0,
        issues
      };
    } catch (error) {
      console.error('خطا در اعتبارسنجی ساختار:', error);
      throw new Error('خطا در اعتبارسنجی ساختار');
    }
  }

  /**
   * تبدیل مدل Prisma به گره سلسله‌مراتبی
   */
  private mapToHierarchyNode(mainDim: MainDimension & {
    subDimensions: Array<SubDimension & {
      aspects: Array<Aspect & {
        subCategories: SubCategory[];
      }>;
    }>;
  }): HierarchyNode {
    return {
      id: mainDim.id,
      code: mainDim.code,
      name: mainDim.name,
      description: mainDim.description || undefined,
      weight: mainDim.weight,
      order: mainDim.order,
      level: 'main',
      children: mainDim.subDimensions.map((sd) => ({
        id: sd.id,
        code: sd.code,
        name: sd.name,
        description: sd.description || undefined,
        weight: sd.weight,
        order: sd.order,
        level: 'sub',
        children: sd.aspects.map((as) => ({
          id: as.id,
          code: as.code,
          name: as.name,
          description: as.description || undefined,
          weight: as.weight,
          order: as.order,
          level: 'aspect',
          children: as.subCategories.map((sc) => ({
            id: sc.id,
            code: sc.code,
            name: sc.name,
            description: sc.description || undefined,
            weight: sc.weight,
            order: sc.order,
            level: 'category'
          }))
        }))
      }))
    };
  }
}

// ایجاد نمونه singleton از سرویس
export const hierarchyService = new HierarchyService();