import { PrismaClient, Todo } from '@prisma/client';

const prisma = new PrismaClient();

export interface TodoCreateInput {
  title: string;
  description?: string;
  status?: 'pending' | 'in_progress' | 'completed' | 'archived';
  priority?: 'low' | 'medium' | 'high' | 'critical';
  category?: 'backend' | 'frontend' | 'database' | 'api' | 'ui' | 'testing' | 'documentation' | 'general';
  tags?: string[];
  dueDate?: string;
}

export interface TodoUpdateInput {
  title?: string;
  description?: string;
  status?: 'pending' | 'in_progress' | 'completed' | 'archived';
  priority?: 'low' | 'medium' | 'high' | 'critical';
  category?: 'backend' | 'frontend' | 'database' | 'api' | 'ui' | 'testing' | 'documentation' | 'general';
  tags?: string[];
  dueDate?: string | null;
  completedAt?: string | null;
}

export interface TodoFilters {
  status?: string;
  priority?: string;
  category?: string;
  search?: string;
  limit?: number;
  offset?: number;
}

export class TodoService {
  async getTodos(filters: TodoFilters = {}): Promise<Todo[]> {
    try {
      const where: any = {};

      if (filters.status) {
        where.status = filters.status;
      }

      if (filters.priority) {
        where.priority = filters.priority;
      }

      if (filters.category) {
        where.category = filters.category;
      }

      if (filters.search) {
        where.OR = [
          { title: { contains: filters.search } },
          { description: { contains: filters.search } },
        ];
      }

      const todos = await prisma.todo.findMany({
        where,
        take: filters.limit || 100,
        skip: filters.offset || 0,
        orderBy: [
          { dueDate: 'asc' },
          { priority: 'desc' },
          { createdAt: 'desc' },
        ],
      });

      return todos;
    } catch (error) {
      console.error('خطا در دریافت لیست todos:', error);
      throw new Error('خطا در دریافت لیست todos');
    }
  }

  async getTodoById(id: string): Promise<Todo | null> {
    try {
      return await prisma.todo.findUnique({
        where: { id },
      });
    } catch (error) {
      console.error('خطا در دریافت اطلاعات todo:', error);
      throw new Error('خطا در دریافت اطلاعات todo');
    }
  }

  async createTodo(data: TodoCreateInput): Promise<Todo> {
    try {
      return await prisma.todo.create({
        data: {
          title: data.title,
          description: data.description,
          status: data.status || 'pending',
          priority: data.priority || 'medium',
          category: data.category || 'general',
          tags: data.tags ? data.tags : undefined,
          dueDate: data.dueDate ? new Date(data.dueDate) : undefined,
        },
      });
    } catch (error) {
      console.error('خطا در ایجاد todo:', error);
      throw new Error('خطا در ایجاد todo');
    }
  }

  async updateTodo(id: string, data: TodoUpdateInput): Promise<Todo> {
    try {
      const updateData: any = {};

      if (data.title !== undefined) updateData.title = data.title;
      if (data.description !== undefined) updateData.description = data.description;
      if (data.status !== undefined) updateData.status = data.status;
      if (data.priority !== undefined) updateData.priority = data.priority;
      if (data.category !== undefined) updateData.category = data.category;
      if (data.tags !== undefined) updateData.tags = data.tags;

      if (data.dueDate !== undefined) {
        updateData.dueDate = data.dueDate ? new Date(data.dueDate) : null;
      }

      if (data.completedAt !== undefined) {
        updateData.completedAt = data.completedAt ? new Date(data.completedAt) : null;
      }

      return await prisma.todo.update({
        where: { id },
        data: updateData,
      });
    } catch (error) {
      console.error('خطا در به‌روزرسانی todo:', error);
      throw new Error('خطا در به‌روزرسانی todo');
    }
  }

  async deleteTodo(id: string): Promise<Todo> {
    try {
      return await prisma.todo.delete({
        where: { id },
      });
    } catch (error) {
      console.error('خطا در حذف todo:', error);
      throw new Error('خطا در حذف todo');
    }
  }

  async getTodoStatistics() {
    try {
      const total = await prisma.todo.count();
      const pending = await prisma.todo.count({ where: { status: 'pending' } });
      const inProgress = await prisma.todo.count({ where: { status: 'in_progress' } });
      const completed = await prisma.todo.count({ where: { status: 'completed' } });
      const archived = await prisma.todo.count({ where: { status: 'archived' } });

      const overdue = await prisma.todo.count({
        where: {
          dueDate: { lt: new Date() },
          status: { not: 'completed' },
        },
      });

      return {
        total,
        pending,
        inProgress,
        completed,
        archived,
        overdue,
      };
    } catch (error) {
      console.error('خطا در دریافت آمار todos:', error);
      throw new Error('خطا در دریافت آمار todos');
    }
  }
}

export const todoService = new TodoService();