// ============================================
// History Service
// Ingests historical market data (price series) and news from the BRS API
// into the database. Designed to be idempotent (upsert by unique key).
// ============================================

import { PrismaClient } from "@prisma/client";
import { fetchPriceHistory, fetchNews } from "@/lib/brs-client";
import type { PriceHistoryPoint } from "@/lib/brs-types";

const prisma = new PrismaClient();

export interface IngestSymbolResult {
  symbolId: string;
  isin: string;
  symbol: string;
  requested: number;
  inserted: number;
  updated: number;
  skipped: number;
  source: string;
  error?: string;
}

export interface IngestAllResult {
  total: number;
  succeeded: number;
  failed: number;
  skipped: number;
  details: IngestSymbolResult[];
  startedAt: Date;
  finishedAt: Date;
}

export interface BackfillOptions {
  top?: number;
  limit?: number;
  batchSize?: number;
  delayMs?: number;
  startDate?: Date;
  endDate?: Date;
  categories?: string[];
  newsCount?: number;
}

const DEFAULT_TOP = 365;
const DEFAULT_BATCH_SIZE = 10;
const DEFAULT_DELAY_MS = 500;
const DEFAULT_NEWS_COUNT = 100;

export class HistoryService {
  /**
   * Ingest historical price series for a single symbol into MarketData.
   * Uses upsert on the (symbolId, date) unique constraint.
   */
  async ingestPriceHistoryForSymbol(
    symbolId: string,
    isin: string,
    symbol: string,
    top = DEFAULT_TOP,
    startDate?: Date,
    endDate?: Date,
  ): Promise<IngestSymbolResult> {
    const result: IngestSymbolResult = {
      symbolId,
      isin,
      symbol,
      requested: 0,
      inserted: 0,
      updated: 0,
      skipped: 0,
      source: "fallback",
    };

    try {
      const { data, source } = await fetchPriceHistory(isin, top);
      result.source = source;
      result.requested = data.length;

      for (const point of data) {
        const pointDate = new Date(point.date);
        pointDate.setUTCHours(0, 0, 0, 0);

        if (startDate && pointDate < startDate) {
          result.skipped++;
          continue;
        }
        if (endDate && pointDate > endDate) {
          result.skipped++;
          continue;
        }

        const { inserted, updated } = await this.upsertMarketData(symbolId, point);
        result.inserted += inserted;
        result.updated += updated;
      }
    } catch (error) {
      result.error = error instanceof Error ? error.message : "خطای ناشناخته";
    }

    return result;
  }

  /** Upsert a single historical point into MarketData */
  private async upsertMarketData(
    symbolId: string,
    p: PriceHistoryPoint,
  ): Promise<{ inserted: number; updated: number }> {
    const date = new Date(p.date);
    date.setUTCHours(0, 0, 0, 0);

    const change = p.close - p.yesterdayPrice;
    const changePercent = p.yesterdayPrice !== 0 ? (change / p.yesterdayPrice) * 100 : 0;

    const data = {
      price: p.close,
      change,
      changePercent,
      volume: p.volume,
      tradeCount: p.tradeCount,
      yesterdayPrice: p.yesterdayPrice,
      openPrice: p.open,
      highPrice: p.high,
      lowPrice: p.low,
      closePrice: p.close,
    };

    const existing = await prisma.marketData.findUnique({
      where: { symbolId_date: { symbolId, date } },
      select: { id: true },
    });

    if (existing) {
      await prisma.marketData.update({
        where: { symbolId_date: { symbolId, date } },
        data,
      });
      return { inserted: 0, updated: 1 };
    }

    await prisma.marketData.create({ data: { symbolId, date, ...data } });
    return { inserted: 1, updated: 0 };
  }

  /**
   * Ingest price history for all symbols (optionally limited).
   * Processes symbols sequentially to respect API rate limits.
   */
  async ingestAllSymbolsPriceHistory(options: BackfillOptions = {}): Promise<IngestAllResult> {
    const top = options.top || DEFAULT_TOP;
    const limit = options.limit;
    const batchSize = options.batchSize || DEFAULT_BATCH_SIZE;
    const delayMs = options.delayMs || DEFAULT_DELAY_MS;
    const startDate = options.startDate;
    const endDate = options.endDate;

    const symbols = await prisma.symbol.findMany({
      select: { id: true, isin: true, symbol: true },
      take: limit,
      orderBy: { symbol: "asc" },
    });

    const details: IngestSymbolResult[] = [];
    let succeeded = 0;
    let failed = 0;
    let skipped = 0;

    const startedAt = new Date();

    for (let i = 0; i < symbols.length; i++) {
      const sym = symbols[i];

      if (i > 0 && i % batchSize === 0) {
        await this.delay(delayMs);
      }

      const r = await this.ingestPriceHistoryForSymbol(sym.id, sym.isin, sym.symbol, top, startDate, endDate);
      details.push(r);

      if (r.error) {
        failed++;
      } else if (r.skipped > 0 && r.inserted === 0 && r.updated === 0) {
        skipped++;
      } else {
        succeeded++;
      }
    }

    return {
      total: symbols.length,
      succeeded,
      failed,
      skipped,
      details,
      startedAt,
      finishedAt: new Date(),
    };
  }

  /**
   * Fetch and persist news items into the News table.
   * If no real news is returned by the API, nothing fake is persisted.
   */
  async syncNews(category = "", count = 20): Promise<{ requested: number; saved: number; source: string }> {
    const { data, source } = await fetchNews(category, count);
    let saved = 0;

    for (const item of data) {
      const publishedAt = this.parseNewsDate(item.date);
      await prisma.news.upsert({
        where: { url: item.url },
        create: {
          title: item.title,
          url: item.url,
          snippet: item.snippet || null,
          source: item.source || null,
          category: item.category || (category || null),
          publishedAt,
        },
        update: {
          title: item.title,
          snippet: item.snippet || null,
          source: item.source || null,
          category: item.category || (category || null),
          publishedAt,
        },
      });
      saved++;
    }

    return { requested: data.length, saved, source };
  }

  /**
   * Sync historical news from multiple categories.
   */
  async syncNewsHistory(
    categories: string[] = [],
    countPerCategory = 100,
  ): Promise<{ requested: number; saved: number; source: string; errors: string[] }> {
    let totalSaved = 0;
    let totalRequested = 0;
    const errors: string[] = [];
    let lastSource = "fallback";

    for (const category of categories) {
      try {
        const { data, source } = await fetchNews(category, countPerCategory);
        lastSource = source;
        totalRequested += data.length;

        for (const item of data) {
          const publishedAt = this.parseNewsDate(item.date);
          await prisma.news.upsert({
            where: { url: item.url },
            create: {
              title: item.title,
              url: item.url,
              snippet: item.snippet || null,
              source: item.source || null,
              category: item.category || category || null,
              publishedAt,
            },
            update: {
              title: item.title,
              snippet: item.snippet || null,
              source: item.source || null,
              category: item.category || category || null,
              publishedAt,
            },
          });
          totalSaved++;
        }
      } catch (error) {
        errors.push(`خطا در همگام‌سازی اخبار دسته ${category}: ${error instanceof Error ? error.message : "خطای ناشناخته"}`);
      }
    }

    return { requested: totalRequested, saved: totalSaved, source: lastSource, errors };
  }

  /**
   * Comprehensive backfill: prices + news for the last year.
   */
  async comprehensiveBackfill(options: BackfillOptions = {}): Promise<{
    prices: IngestAllResult;
    news: { requested: number; saved: number; source: string; errors: string[] };
    totalDuration: number;
  }> {
    const oneYearAgo = new Date();
    oneYearAgo.setFullYear(oneYearAgo.getFullYear() - 1);

    const backfillOptions: BackfillOptions = {
      top: options.top || DEFAULT_TOP,
      limit: options.limit,
      batchSize: options.batchSize || DEFAULT_BATCH_SIZE,
      delayMs: options.delayMs || DEFAULT_DELAY_MS,
      startDate: options.startDate || oneYearAgo,
      endDate: options.endDate,
    };

    const startTime = Date.now();

    const prices = await this.ingestAllSymbolsPriceHistory(backfillOptions);

    const newsCategories = options.categories || ["", "بورس", "اقتصاد", "سیاسی"];
    const news = await this.syncNewsHistory(newsCategories, options.newsCount || DEFAULT_NEWS_COUNT);

    const totalDuration = Date.now() - startTime;

    return { prices, news, totalDuration };
  }

  /** Read stored price history for a symbol with optional date range */
  async getPriceHistory(
    symbolId: string,
    startDate?: Date,
    endDate?: Date,
  ): Promise<{ date: Date; close: number; volume: number }[]> {
    const where: { symbolId: string; date?: { gte?: Date; lte?: Date } } = { symbolId };
    if (startDate || endDate) {
      where.date = {};
      if (startDate) where.date.gte = startDate;
      if (endDate) where.date.lte = endDate;
    }

    const rows = await prisma.marketData.findMany({
      where,
      orderBy: { date: "asc" },
      select: { date: true, closePrice: true, volume: true },
    });

    return rows.map((r) => ({ date: r.date, close: r.closePrice, volume: r.volume }));
  }

  /** Read stored news */
  async getNews(limit = 50, category?: string) {
    return prisma.news.findMany({
      where: category ? { category } : undefined,
      orderBy: [{ publishedAt: "desc" }, { fetchedAt: "desc" }],
      take: limit,
    });
  }

  /** Get backfill statistics */
  async getBackfillStatistics() {
    const [
      totalSymbols,
      symbolsWithHistory,
      totalMarketDataRows,
      dateRange,
      totalNews,
      recentNews,
    ] = await Promise.all([
      prisma.symbol.count(),
      prisma.symbol.count({ where: { marketData: { some: {} } } }),
      prisma.marketData.count(),
      prisma.marketData.findFirst({ orderBy: { date: "desc" }, select: { date: true } }),
      prisma.news.count(),
      prisma.news.count({ where: { publishedAt: { gte: new Date(Date.now() - 30 * 24 * 60 * 60 * 1000) } } }),
    ]);

    const oldestData = await prisma.marketData.findFirst({ orderBy: { date: "asc" }, select: { date: true } });

    return {
      totalSymbols,
      symbolsWithHistory,
      symbolsWithoutHistory: totalSymbols - symbolsWithHistory,
      totalMarketDataRows,
      oldestDataDate: oldestData?.date || null,
      latestDataDate: dateRange?.date || null,
      totalNews,
      recentNews30Days: recentNews,
    };
  }

  private parseNewsDate(date: string): Date | null {
    if (!date) return null;
    const d = new Date(date);
    return isNaN(d.getTime()) ? null : d;
  }

  private delay(ms: number): Promise<void> {
    return new Promise((resolve) => setTimeout(resolve, ms));
  }
}

export const historyService = new HistoryService();
